-- Neomatra bilingual knowledge dataset V3
-- Existing table/migrations must already exist. Embeddings are intentionally NULL and should be rebuilt after import.
SET NAMES utf8mb4;
START TRANSACTION;
SET @knowledge_category_id := (SELECT id FROM categories WHERE slug = 'panduan-neomatra' LIMIT 1);

-- Deactivate legacy pre-Neomatra chatbot knowledge that conflicts with the current project scope.
UPDATE knowledge_items SET is_active = 0, updated_at = CURRENT_TIMESTAMP
WHERE title IN ('Tentang Semantic Chatbot Lite','Cara chatbot menggunakan knowledge','Ketika informasi tidak tersedia');

CREATE TEMPORARY TABLE `_neomatra_knowledge_seed` (
  `title` varchar(255) NOT NULL PRIMARY KEY,
  `content` text NOT NULL,
  `keywords` json DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `sort_order` int unsigned NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `_neomatra_knowledge_seed` (`title`,`content`,`keywords`,`is_featured`,`sort_order`) VALUES
('Tentang Neomatra / About Neomatra', 'ID: Neomatra adalah aplikasi pencarian dan perbandingan produk teknologi yang membantu pengguna menemukan listing baru atau bekas yang berpotensi berada di bawah harga pasar. Sistem menggabungkan semantic search, dataset marketplace, kondisi, seller type, biaya total, risk signal, dan ranking. EN: Neomatra is a technology product search and comparison application that helps users find new or used listings that may be priced below the estimated market level. It combines semantic search, marketplace datasets, condition, seller type, total cost, risk signals, and ranking.', '["neomatra","intro","about","tentang"]', 1, 10),
('Kategori yang didukung / Supported categories', 'ID: Neomatra Lite memprioritaskan PC Components, Handphone, Laptop, PC Accessories, serta Networking seperti router, access point, switch, modem, dan network adapter. Permintaan di luar kategori ini diarahkan ke pilihan kategori yang tersedia atau pencarian eksternal. EN: Neomatra Lite prioritizes PC Components, Phones, Laptops, PC Accessories, and Networking such as routers, access points, switches, modems, and network adapters. Requests outside these categories are guided to supported categories or external search.', '["category","kategori","pc","phone","laptop","networking"]', 1, 20),
('Platform yang didukung / Supported platforms', 'ID: Registry platform dapat memuat Tokopedia, Shopee, OLX, Facebook Marketplace, Carousell, Blibli, Lazada, TikTok Shop, Jagofon, Laku6, dan sumber teknologi lain. Hanya connector yang benar-benar tersedia yang boleh disebut sebagai sumber sinkronisasi otomatis. EN: The platform registry can contain Tokopedia, Shopee, OLX, Facebook Marketplace, Carousell, Blibli, Lazada, TikTok Shop, Jagofon, Laku6, and other technology sources. Only connectors that are actually implemented may be described as automatically synchronized sources.', '["platform","marketplace","tokopedia","shopee","olx"]', 1, 30),
('Data demo dan data live / Demo data and live data', 'ID: Listing demo adalah data buatan yang diberi label jelas untuk pengujian dan portofolio. Listing demo tidak boleh disebut harga atau stok real-time. EN: Demo listings are clearly labeled synthetic records for testing and portfolio use. Demo listings must never be presented as real-time prices or stock.', '["demo","live","real time","dataset"]', 1, 40),
('Barang baru dan bekas / New and used items', 'ID: Neomatra membedakan kondisi new dan used agar market comparison tidak mencampur barang baru dengan barang bekas. Kondisi lain dapat mencakup open_box, refurbished, ex_display, dan unknown. EN: Neomatra separates new and used conditions so market comparison does not mix new items with second-hand items. Other conditions may include open_box, refurbished, ex_display, and unknown.', '["new","used","baru","bekas","condition"]', 1, 50),
('Open box, refurbished, dan ex-display', 'ID: Open box berarti kemasan sudah dibuka tetapi produk belum tentu pernah digunakan secara normal. Refurbished berarti produk telah diperbaiki atau dipulihkan. Ex-display berarti produk pernah menjadi unit pajangan. Ketiganya tidak otomatis disamakan dengan new. EN: Open-box products have opened packaging, refurbished products have been restored or repaired, and ex-display products were used as display units. They should not automatically be treated as new.', '["open box","refurbished","ex display","condition"]', 0, 60),
('Seller type Neomatra / Neomatra seller types', 'ID: Seller type internal terdiri dari official, store, reseller, individual, dan unknown. Klasifikasi hanya dibuat dari sinyal yang dapat dibuktikan. EN: Internal seller types are official, store, reseller, individual, and unknown. Classification should only use evidence that can be supported.', '["seller","official","store","reseller","individual"]', 0, 70),
('Arti official seller / Meaning of official seller', 'ID: Nama toko yang mengandung kata Official tidak cukup untuk menetapkan seller_type=official. Status official harus berasal dari metadata platform atau verifikasi admin. EN: A seller name containing the word Official is not enough to assign seller_type=official. Official status must come from platform metadata or administrator verification.', '["official seller","verified seller","seller type"]', 0, 80),
('Harga pasar / Market price', 'ID: Market price adalah estimasi backend berdasarkan listing pembanding yang relevan. Nilai ini bukan harga resmi dan dapat berubah sesuai sample, kondisi, varian, lokasi, serta freshness data. EN: Market price is a backend estimate derived from relevant comparable listings. It is not an official price and can change with sample size, condition, variant, location, and data freshness.', '["market price","harga pasar","median","estimate"]', 1, 90),
('Comparable listings', 'ID: Listing hanya boleh masuk perhitungan harga pasar jika canonical product, varian kritis, currency, dan condition sesuai aturan comparable. EN: A listing should only be used in market-price calculations when its canonical product, critical variant, currency, and condition satisfy the comparable rules.', '["comparable","comparison","listing","variant"]', 1, 100),
('Persentase undervalued / Undervalued percentage', 'ID: Undervalued menunjukkan seberapa jauh total cost listing berada di bawah estimasi market price. Nilai positif bukan jaminan keuntungan dan harus dibaca bersama risk signal serta kualitas comparable. EN: Undervalued percentage indicates how far a listing''s total cost is below the estimated market price. A positive value does not guarantee profit and should be interpreted with risk signals and comparable quality.', '["undervalued","percentage","harga murah","market price"]', 1, 110),
('Total cost', 'ID: Total cost dapat mencakup harga listing, shipping cost, service fee, inspection cost, dan repair estimate jika tersedia. Komponen yang tidak diketahui tidak boleh dibuat-buat oleh AI. EN: Total cost can include listing price, shipping cost, service fee, inspection cost, and repair estimate when available. Unknown cost components must not be invented by the AI.', '["total cost","shipping","fee","repair","inspection"]', 0, 120),
('Estimasi margin reseller / Reseller margin estimate', 'ID: Margin reseller adalah estimasi selisih antara market price dan total cost berdasarkan aturan backend. Nilai ini bersifat informasional dan bukan jaminan laba. EN: Reseller margin is an estimated difference between market price and total cost based on backend rules. It is informational and does not guarantee profit.', '["margin","reseller","profit","laba"]', 1, 130),
('Risk signal', 'ID: Risk signal adalah sinyal ranking yang menjelaskan faktor seperti seller type, kondisi, harga, freshness, dan informasi listing. Risk signal tidak boleh menyatakan seller sebagai penipu atau menjamin seller aman. EN: Risk signals are ranking indicators based on factors such as seller type, condition, price, freshness, and listing information. They must not label a seller as fraudulent or guarantee safety.', '["risk","risk signal","seller safety","ranking"]', 1, 140),
('Freshness listing / Listing freshness', 'ID: source_published_at dan last_synced_at digunakan untuk menilai usia data. Listing lama dapat diberi penalti atau label stale agar tidak terlihat sama segarnya dengan listing baru. EN: source_published_at and last_synced_at are used to assess data age. Older listings can receive a stale label or ranking penalty so they are not presented as equally fresh as recent data.', '["freshness","stale","last synced","published"]', 0, 150),
('Semantic search', 'ID: Semantic search mengubah query menjadi embedding dan mencari product, alias, atau knowledge yang paling dekat secara makna. Semantic similarity bukan izin untuk mengabaikan atribut kritis produk. EN: Semantic search converts a query into an embedding and retrieves products, aliases, or knowledge that are semantically similar. Semantic similarity does not override critical product attributes.', '["semantic","embedding","cosine","search"]', 1, 160),
('Product alias', 'ID: Product alias membantu mencocokkan penulisan berbeda seperti RTX3060, RTX 3060, atau VGA RTX 3060 ke canonical product yang sama bila varian kritis sesuai. EN: Product aliases help map different spellings such as RTX3060, RTX 3060, or VGA RTX 3060 to the same canonical product when critical variants match.', '["alias","canonical product","synonym","normalization"]', 0, 170),
('Query dengan budget / Budget query', 'ID: Pengguna dapat menyertakan budget seperti di bawah 4 juta atau maksimum Rp4.000.000. Parser harus menormalisasi nilai uang sebelum filtering. EN: Users can include budgets such as under 4 million or maximum IDR 4,000,000. The parser should normalize currency values before filtering.', '["budget","harga","price filter","rupiah"]', 0, 180),
('Query dengan lokasi / Location query', 'ID: Lokasi digunakan sebagai filter atau preferensi jika data listing memilikinya. Jika filter lokasi terlalu ketat, sistem dapat menawarkan hasil dari area lain secara transparan. EN: Location is used as a filter or preference when listing data provides it. If the location filter is too strict, the system may transparently offer results from other areas.', '["location","lokasi","surabaya","jakarta"]', 0, 190),
('Query dengan platform / Platform query', 'ID: Jika user meminta platform tertentu, Neomatra memprioritaskan platform tersebut jika tersedia. Jika connector atau dataset platform tidak tersedia, sistem menawarkan platform aktif lain atau link pencarian eksternal. EN: If the user requests a specific platform, Neomatra prioritizes it when available. If that platform''s connector or dataset is unavailable, the system offers other active platforms or an external search link.', '["platform filter","marketplace","connector"]', 0, 200),
('Filter terlalu ketat / Filters too strict', 'ID: Jika product valid tetapi kombinasi budget, seller, lokasi, kondisi, atau platform menghasilkan nol listing, sistem menandai FILTER_TOO_STRICT dan dapat melonggarkan filter opsional secara bertahap. EN: If the product is valid but a combination of budget, seller, location, condition, or platform returns zero listings, the system marks FILTER_TOO_STRICT and may progressively relax optional filters.', '["filter too strict","fallback","relax filter"]', 1, 210),
('Permintaan di luar scope / Out-of-scope request', 'ID: Jika user meminta kategori di luar dataset Neomatra Lite, sistem tidak mengarang listing. Sistem menjelaskan kategori aktif, menawarkan item terkait dalam dataset, atau memberikan tautan pencarian eksternal yang relevan. EN: If a user requests a category outside Neomatra Lite, the system must not invent listings. It explains supported categories, offers related in-dataset items, or provides a relevant external search link.', '["out of scope","unsupported","validation","guidance"]', 1, 220),
('Produk tidak dikenali / Unknown product', 'ID: Jika nama model tidak dapat dipetakan dengan exact match, alias, atau semantic candidate yang cukup kuat, sistem meminta klarifikasi seperti brand, model, varian, atau kategori. EN: If a model cannot be mapped through exact matching, aliases, or a sufficiently strong semantic candidate, the system asks for clarification such as brand, model, variant, or category.', '["unknown product","clarification","model","brand"]', 0, 230),
('Tidak ada listing aktif / No active listing', 'ID: Jika canonical product dikenali tetapi tidak ada listing aktif, sistem mempertahankan identitas produk dan menawarkan platform lain, filter yang lebih longgar, atau produk alternatif yang dekat. EN: If the canonical product is recognized but no active listing exists, the system keeps the product identity and offers other platforms, relaxed filters, or closely related alternatives.', '["no listing","no active listing","fallback"]', 0, 240),
('Platform tidak tersedia / Platform unavailable', 'ID: Jika satu platform gagal atau tidak memiliki connector aktif, Neomatra menampilkan hasil platform lain dan menyatakan sumber yang tidak tersedia tanpa menggagalkan seluruh pencarian. EN: If one platform fails or lacks an active connector, Neomatra returns results from other platforms and clearly identifies the unavailable source instead of failing the entire search.', '["platform unavailable","connector error","partial"]', 0, 250),
('Search timeout', 'ID: Jika pencarian melampaui time budget, sistem dapat mengembalikan partial results dari sumber yang sudah selesai dan menandai status timeout. Hasil yang sudah valid tidak perlu dibuang. EN: If a search exceeds its time budget, the system may return partial results from completed sources and mark the request as timed out. Valid results already obtained should not be discarded.', '["timeout","search duration","partial result"]', 0, 260),
('Partial results', 'ID: Partial result berarti hanya sebagian platform atau tahap retrieval yang berhasil. UI harus menjelaskan sumber mana yang berhasil dan mana yang belum tersedia. EN: A partial result means only some platforms or retrieval stages succeeded. The UI should explain which sources succeeded and which were unavailable.', '["partial","result status","source"]', 0, 270),
('Progressive fallback', 'ID: Fallback pencarian mengikuti urutan exact structured matching, semantic plus alias matching, relaksasi filter opsional, lalu related product atau external handoff. Fallback bukan sekadar mengulang call LLM yang sama. EN: Search fallback follows exact structured matching, semantic plus alias matching, optional-filter relaxation, then related-product or external handoff. Fallback is not repeated identical LLM calls.', '["fallback","attempt","exact","semantic"]', 1, 280),
('External platform handoff', 'ID: Jika item berada di luar dataset tetapi pencarian eksternal masih berguna, Neomatra dapat menawarkan link platform yang relevan. Link eksternal tidak boleh disajikan seolah-olah Neomatra telah memverifikasi harga, stok, atau keamanan listing tersebut. EN: When an item is outside the dataset but external search remains useful, Neomatra may offer a relevant platform link. External links must not imply that Neomatra verified the listing''s price, stock, or safety.', '["external link","handoff","out of scope"]', 0, 290),
('Bahasa Indonesia dan English / Indonesian and English', 'ID: Neomatra mendukung Bahasa Indonesia dan English. UI preference dan bahasa query dapat diperlakukan terpisah. Respons sebaiknya mengikuti kebijakan language switch tanpa mengubah canonical product data. EN: Neomatra supports Indonesian and English. UI preference and query language can be handled separately. Responses should follow the language-switch policy without changing canonical product data.', '["language","bahasa","english","indonesia"]', 1, 300),
('Query campuran bahasa / Mixed-language query', 'ID: Query seperti ''cari used RTX 3060 under 4 juta'' tetap dapat dinormalisasi menjadi intent, product, condition, dan budget yang sama. EN: A mixed-language query such as ''cari used RTX 3060 under 4 juta'' can still be normalized into the same intent, product, condition, and budget.', '["mixed language","code switching","query"]', 0, 310),
('Cara membuat query yang baik / How to write a good query', 'ID: Query yang baik menyebut produk atau kategori, kondisi, budget, lokasi, dan platform bila penting. Contoh: ''Cari RTX 3060 Ti bekas di bawah 4 juta di Surabaya.'' EN: A useful query includes product or category, condition, budget, location, and platform when important. Example: ''Find a used RTX 3060 Ti under IDR 4 million in Surabaya.''', '["query guide","search guide","example"]', 1, 320),
('Perbandingan dua produk / Comparing two products', 'ID: Jika user membandingkan dua produk, Neomatra harus menjaga masing-masing canonical product dan atribut kritis tetap terpisah. Harga pasar tidak boleh dicampur antar-model. EN: When comparing two products, Neomatra must keep each canonical product and critical attributes separate. Market-price samples must not be mixed across models.', '["compare","comparison","two products"]', 0, 330),
('Mengapa ranking berbeda / Why rankings differ', 'ID: Ranking dapat berbeda walaupun harga hampir sama karena relevance, total cost, condition, seller type, freshness, dan risk signal ikut diperhitungkan. EN: Rankings may differ even when prices are similar because relevance, total cost, condition, seller type, freshness, and risk signals also contribute.', '["ranking","score","why ranked"]', 0, 340),
('Unanswered query logging', 'ID: Query yang tidak menghasilkan jawaban memadai dapat dicatat untuk evaluasi admin. Log membantu menemukan alias, kategori, knowledge, atau scenario yang masih kurang. EN: Queries that do not produce adequate answers can be logged for administrator review. Logs help identify missing aliases, categories, knowledge, or scenarios.', '["unanswered","query log","admin","evaluation"]', 0, 350),
('Admin memperbarui knowledge / Admin knowledge updates', 'ID: Admin dapat menambah, mengubah, mengaktifkan, menonaktifkan, dan menghapus knowledge sesuai hak akses. Embedding perlu dibangun ulang ketika konten knowledge berubah. EN: Administrators can create, edit, activate, deactivate, and delete knowledge according to authorization. Embeddings need rebuilding when knowledge content changes.', '["admin","knowledge","embedding rebuild"]', 0, 360),
('Jangan kirim credential / Do not submit credentials', 'ID: Pengguna tidak perlu memasukkan password, API key, OTP, nomor kartu, atau credential pribadi ke chatbot. Data tersebut tidak diperlukan untuk pencarian produk. EN: Users should not submit passwords, API keys, OTP codes, payment-card numbers, or personal credentials to the chatbot. Such data is not required for product search.', '["credential","password","otp","privacy"]', 1, 370),
('Intent non-shopping / Non-shopping intent', 'ID: Untuk permintaan yang tidak berkaitan dengan fungsi Neomatra, sistem mengarahkan user kembali ke pencarian, perbandingan, kondisi, harga, seller, atau platform yang didukung. EN: For requests unrelated to Neomatra''s function, the system guides the user back to supported product search, comparison, condition, pricing, seller, or platform tasks.', '["non shopping","unsupported intent","guidance"]', 0, 380),
('Source URL dan timestamp', 'ID: Hasil listing harus mempertahankan source URL dan timestamp yang tersedia agar pengguna dapat menelusuri sumber dan menilai freshness. EN: Listing results should retain source URLs and available timestamps so users can trace the source and assess freshness.', '["source url","timestamp","traceability"]', 0, 390),
('Harga bukan jaminan / Prices are not guaranteed', 'ID: Harga listing dapat berubah setelah data diambil. Neomatra menampilkan informasi berdasarkan data yang tersedia pada waktu fetch dan tidak menjamin harga akhir di platform sumber. EN: Listing prices may change after retrieval. Neomatra reports available data at fetch time and does not guarantee the final price on the source platform.', '["price change","disclaimer","fetched at"]', 0, 400),
('Pemeriksaan kondisi barang bekas / Used-item condition check', 'ID: Untuk barang bekas, pengguna sebaiknya memeriksa foto, kelengkapan, fungsi utama, warranty, riwayat perbaikan, dan kondisi fisik sebelum transaksi. Neomatra hanya membantu menyusun sinyal informasi. EN: For used items, users should review photos, included accessories, core functionality, warranty, repair history, and physical condition before transacting. Neomatra only provides informational signals.', '["used item","inspection","condition","warranty"]', 0, 410),
('PC component critical attributes', 'ID: Untuk komponen PC, atribut kritis seperti model GPU, VRAM, socket CPU, chipset motherboard, kapasitas RAM/SSD, dan wattage PSU perlu cocok sebelum listing dihitung comparable. EN: For PC components, critical attributes such as GPU model, VRAM, CPU socket, motherboard chipset, RAM/SSD capacity, and PSU wattage should match before listings are treated as comparable.', '["pc component","gpu","cpu","ram","ssd","psu"]', 0, 420),
('Laptop critical attributes', 'ID: Laptop dengan nama family yang sama dapat memiliki CPU, RAM, storage, GPU, atau SKU berbeda. Canonical product harus sedapat mungkin menggunakan konfigurasi yang cukup spesifik untuk perbandingan harga. EN: Laptops with the same family name may have different CPU, RAM, storage, GPU, or SKU. Canonical products should use sufficiently specific configurations for price comparison.', '["laptop","sku","configuration","variant"]', 0, 430),
('Smartphone critical attributes', 'ID: Smartphone harus dibedakan berdasarkan model dan storage, serta RAM jika varian tersebut memengaruhi identitas pasar. Contoh 128 GB dan 256 GB tidak boleh otomatis digabung dalam market median yang sama. EN: Smartphones should be separated by model and storage, and by RAM when that variant affects market identity. A 128 GB and 256 GB version should not automatically share the same market median.', '["smartphone","storage","ram","variant"]', 0, 440),
('Networking critical attributes', 'ID: Router dan perangkat jaringan perlu memperhatikan model, Wi-Fi generation, class, port, dan device type. Router, access point, switch, modem, dan network adapter tidak boleh diperlakukan sebagai satu jenis produk. EN: Networking devices should consider model, Wi-Fi generation, class, ports, and device type. Routers, access points, switches, modems, and network adapters must not be treated as one product type.', '["router","networking","access point","switch","modem"]', 0, 450),
('Kualitas sample market price / Market sample quality', 'ID: Market price lebih dapat dipercaya ketika jumlah comparable cukup, duplikat disaring, kondisi konsisten, dan listing stale tidak mendominasi sample. EN: Market-price estimates are more reliable when enough comparable listings exist, duplicates are filtered, conditions are consistent, and stale listings do not dominate the sample.', '["sample size","median","duplicate","quality"]', 0, 460),
('Duplicate listing handling', 'ID: Listing yang sama dari sinkronisasi berulang tidak boleh dihitung berkali-kali. source_fingerprint dan external listing ID digunakan untuk membantu deduplication. EN: The same listing from repeated synchronization should not be counted multiple times. source_fingerprint and external listing IDs help with deduplication.', '["duplicate","fingerprint","external listing id"]', 0, 470);

UPDATE `knowledge_items` k
JOIN `_neomatra_knowledge_seed` s ON s.title = k.title
SET
  k.content = s.content,
  k.embedding = NULL,
  k.embedding_hash = NULL,
  k.embedding_model = NULL,
  k.embedded_at = NULL,
  k.embedding_error = NULL,
  k.is_active = 1,
  k.is_featured = s.is_featured,
  k.sort_order = s.sort_order,
  k.category_id = @knowledge_category_id,
  k.keywords = s.keywords,
  k.source_name = 'Neomatra Dataset & Taxonomy V3',
  k.source_url = NULL,
  k.embedding_dimensions = NULL,
  k.updated_at = CURRENT_TIMESTAMP;

INSERT INTO `knowledge_items`
(`title`,`content`,`embedding`,`embedding_hash`,`embedding_model`,`embedded_at`,`embedding_error`,
 `is_active`,`is_featured`,`sort_order`,`created_at`,`updated_at`,`category_id`,`keywords`,`source_name`,`source_url`,`embedding_dimensions`)
SELECT
  s.title,
  s.content,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  1,
  s.is_featured,
  s.sort_order,
  CURRENT_TIMESTAMP,
  CURRENT_TIMESTAMP,
  @knowledge_category_id,
  s.keywords,
  'Neomatra Dataset & Taxonomy V3',
  NULL,
  NULL
FROM `_neomatra_knowledge_seed` s
LEFT JOIN `knowledge_items` k ON k.title = s.title
WHERE k.id IS NULL;
DROP TEMPORARY TABLE `_neomatra_knowledge_seed`;
COMMIT;

-- Verification
SELECT COUNT(*) AS active_knowledge_items FROM knowledge_items WHERE is_active = 1;
SELECT COUNT(*) AS v3_knowledge_items FROM knowledge_items WHERE source_name = 'Neomatra Dataset & Taxonomy V3';